                'เลนาและผู้อำนวยการฝ่ายขายยุโรปของ Afarer นำเสนอคอลเลกชันที่งานแสดงสินค้า ISPO Munich ในเดือนพฤศจิกายน 2023 และได้รับคำสั่งซื้อล่วงหน้าจากสาขา Intersport 38 แห่ง ร้าน Globetrotter 12 แห่ง และ Bergfreunde.de Afarer ออกแบบบรรจุภัณฑ์ค้าปลีกพร้อมวางชั้นที่เป็นไปตามกฎหมายบรรจุภัณฑ์เยอรมัน (VerpackG) ได้แก่ กล่องกระดาษรีไซเคิลได้ 100% พิมพ์ด้วยหมึกจากถั่วเหลือง ไม่ใช้ฟิล์มหดพลาสติก และมีคิวอาร์โคดลิงก์ไปยังวิดีโอประกอบการใช้งานความยาว 3 นาทีภาษาเยอรมัน ต้นทุนบรรจุภัณฑ์อยู่ที่ 4.20 ยูโรต่อชิ้น แต่ขจัดปัญหาสินค้าเสียหายในร้านซึ่งเคยสูงถึง 2.3% ในแบรนด์คู่แข่งที่ใช้ถุงพลาสติก',
