                'Afarer ออกแบบ Polar Explorer 12.0 ด้วยการปรับตัวเฉพาะอาร์กติก ได้แก่ สีส้มนานาชาติสว่าง (มองเห็นบนน้ำแข็งได้ 2 กิโลเมตรผ่านกล้องส่องทางไกล) แถบสะท้อนแสงระดับ SOLAS ห่วงกู้ภัยในตัวรับได้ 600 กิโลกรัม (สำหรับซอดิแอคลากกลับ) และกระเป๋าช่องบีคอน GPS ที่หัวกระดาน (Hurtigruten จัดหา Garmin inReach Mini 2) แพ็กเกจรวมเสื้อชูชีพแบบพองได้ใช้กับชุดกันน้ำได้ (Mustang Survival HIT ที่ Afarer ทดสอบเรื่องความคล่องตัวขณะพาย) ชุดถุงมือนีโอพรีนแบบพอกี (แผ่นอุ่นมือในตัวในด้ามไม้พาย) และเป้เฉพาะที่ใส่ลงล็อกเกอร์ซอดิแอคได้ (ขนาดพับแล้ว 60×30×30 เซนติเมตร) ระบบกางใช้จากซอดิแอคคือชั้นวางล้อจ๊อกกี้ที่กากรับกับตัวถังลอยของซอดิแอค ให้ไกด์คนเดียวระดมกระดานลงน้ำได้โดยไม่ต้องยก',
